package com.mall.entity;
import com.baomidou.mybatisplus.annotation.*; import lombok.Data; import java.io.Serializable; import java.time.LocalDateTime;
@Data @TableName("category") public class Category implements Serializable { @TableId(type=IdType.AUTO) private Long id; private Long parentId; private String name; private String icon; private Integer sort; private Integer level; private Integer status; @TableField(fill=FieldFill.INSERT) private LocalDateTime createTime; @TableField(fill=FieldFill.INSERT_UPDATE) private LocalDateTime updateTime; @TableLogic @TableField(fill=FieldFill.INSERT) private Integer deleted; }
